# ── SearchPath model (CSS600 ClassModels / matrix extension) ─────────

struct SearchPathModel <: AbstractBenchmarkModel end

model_name(::SearchPathModel) = "Search Path"
n_ticks(::SearchPathModel) = 100
tracked_globals(::SearchPathModel) = ["numbercaught", "time"]
world_dims(::SearchPathModel) = (0, 9, 0, 9)
topology(::SearchPathModel) = (false, false)

function netlogo_code(::SearchPathModel)
"""
extensions [matrix]
globals [
  searchertransitionmatrix ;; the searchers transition matrix
  targettransitionmatrix ;; the targets actual transition matrix
  targetknowntransitionmatrix ;; the searchers idea of the targets tranision matrix
  numbercaught ;; total number of targets caught
  time ;; time counter
  gridsize ;; size of the grid
  gridlength ;; length of the grid
  probdensity ;; a row representing a probablity density
  probablityofdetection
  currentcellx ;; x value of cueent cell
  currentcelly ;; y calue of cueent cell
  j ;; control variable
  k ;; control variable
  i ;; control variable
  transitionmatrixj
  searchershere ;; number of searchers in a cell
  probtargethere ;; probablity that a target is in a cell
  probdetection ;; probablity of detection
  Pj ;; transitionmatrixj times probnotdetected
  probdom ;; used as the demominators when calculating new probablity distribution
  probnum ;; used as the numerator when calculating new probablity distribution
  newprobdensityj ;; jth element of new probablity density
  rowsum ;; sum of a row
  currentcell ;; current cell number
  randomcell ;; a random cell value to find lottery winner
  cellmax ;; cell in the neighborhood with the highest probablity
  probnotdetected ;; a probablity that a target was not detected
  associationmatrix ;; a matrix of cell associations
  cell1 ;; 1 cell in the moores neighboorhood lower left
  cell2 ;; 2 cell in the moores neighboorhood lower middle
  cell3 ;; 3 cell in the moores neighboorhood lower right
  cell4 ;; 4 cell in the moores neighboorhood middle left
  cell5 ;; 5 cell in the moores neighboorhood middle middle
  cell6 ;; 6 cell in the moores neighboorhood middle right
  cell7 ;; 7 cell in the moores neighboorhood top left
  cell8 ;; 8 cell in the moores neighboorhood top middle
  cell9 ;; 9 cell in the moores neighboorhood top right
  cellprob ;; probablity of a target being in that cell
  probNextmove ;; a estimation of the probablity a target is in the next cell
  probNextmoveactual ;; the actual probablity a target is in the next cell
  temptransitionmatrixj ;; jth row of a temporary transition matrix
  probdensityactual ;; the actual probablity distribution
  confidenceprob ;; a estimated confidance probablity
  confidenceprobactual ;; the actual confidance probablity
  probdensitymatrix ;; a matrix of the probablity density ie multipled by the association matrix
  searcherpositionrow ;; a row of searchers positions
  sensorpositionrow ;; a row of sensors positions
  sumcell1 ;; sum of probabilities to cell 1
  sumcell2 ;; sum of probabilities to cell 2
  sumcell3 ;; sum of probabilities to cell 3
  sumcell4 ;; sum of probabilities to cell 4
  sumcell5 ;; sum of probabilities to cell 5
  sumcell6 ;; sum of probabilities to cell 6
  sumcell7 ;; sum of probabilities to cell 7
  sumcell8 ;; sum of probabilities to cell 8
  sumcell9 ;; sum of probabilities to cell 9
  onesrow ;; a row of ones
  positionrow ;; a row representing the position of searchers
  probofdetection ;; the probablity of detection
  targetstofind ;; number of targets left to find
  expectnumdetetions ;; a expected number of detection on the next move
  lasttargetsfoundsum ;; targets found during the last time step
  currenttargetsfound ;; number of targets found during the last time step
  targetseenat ;; the cell that a target was seen at
  targetmovedto ;; the cell that a target moved to
  myideadata ;; datapoints for my idea
  totalrows ;; total rows of the idea data
  fromrows ;; from rows
  torows ;; to rows
  datadim ;; diminsions of my idea data
  newtranscell ;; new tranistion matrix cell value
  currentx ;; current searchers x
  currenty ;; current searchers y
  cell1taken  ;;taken variable
  cell2taken  ;;taken variable
  cell3taken  ;;taken variable
  cell4taken  ;;taken variable
  cell5taken  ;;taken variable
  cell6taken  ;;taken variable
  cell7taken  ;;taken variable
  cell8taken  ;;taken variable
  cell9taken  ;;taken variable
  NumberofSearchers
  NumberofSensors
  NumberofTargets
  TotalTime
  DetectionRate
  NumberofKnownTargets
  EndonConfidence
  SensorsMove
  ShowPaths
  ExponentialDetection
  TargetsCatch
  SensorsReportTarget
  ShowProbDensity
  showcellnumber
  showcellproblabel
  TargetMovement
  SearcherStrat
  targetknownmovement
  ]
breed [targets target]
breed [searchers searcher]
breed [sensors sensor]
targets-own [
  caught ;; if the target has been caught
  seen ;; if the target has been seen
  free ;; if the target is free
  justseen ;; if the target was just seen
  ]
searchers-own [
  checkpoint
  ]
patches-own [
  prob ;; probablity a target is in the patch
  cellnumber ;; the patches cell number
  ]

;;set up model
to setup
  ;;clear all variables
  clear-all

  ;; Hardcoded UI defaults
  set NumberofSearchers 1
  set NumberofSensors 0
  set NumberofTargets 1
  set TotalTime 10000
  set DetectionRate 0.2
  set NumberofKnownTargets 1
  set EndonConfidence 100
  set SensorsMove false
  set ShowPaths true
  set ExponentialDetection true
  set TargetsCatch true
  set SensorsReportTarget true
  set ShowProbDensity true
  set showcellnumber true
  set showcellproblabel false
  set TargetMovement "gangster3"
  set SearcherStrat "myidea - gangster3"
  set targetknownmovement "Generated"

  ;;set grids length/ used for calculations
  set gridlength 10

  ;; set the gridsize/ used for calculations
  set gridsize gridlength ^ 2

  ;; set initial time
  set time 0

  ;;set up target stat variables
  set lasttargetsfoundsum 0
  set currenttargetsfound 0

  ;; set the number of targets caught
  set numbercaught 0

  ;; set up the probablity density
  setup-probdensity

  ;; set up the patches
  setup-patches

  ;; set up the targets actual transition matrix
  setup-targetmatrix

  ;; set up the searchers idea of the targets transition matrix
  setup-targetknownmatrix

  ;; set up the searchers original transition matrix
  setup-searchermatrix

  ;; set up the ones row/ a row of ones for calculaitons
  setup-onesrow

  ;; set up the position row for the searchers
  setup-update-positionrows

  ;; set up inital statistics
  setup-update-stats

  ;; set up the targets
  setup-targets

  ;; set up the searchers
  setup-searchers

  ;; set up the sensors
  setup-sensors

  ;;update the searchers ideal transition matrix according to new data
  update-searcher-idea-transitionmatrix

  reset-ticks
end

;; set up patches
to setup-patches
  ask patches [
    ;; get the patches x coordinate
    set currentcellx pxcor

    ;; if the patches y cordinate is less than grid length
    ifelse pycor < gridlength
       [set currentcelly pycor] ;; get the patches y coordinate
       [set currentcelly pycor - 1] ;; otherwise get it minus 1

    ;; calculate cell number
    set currentcell currentcelly * gridlength + currentcellx

    ;; if the cell number is negative set it to 0
    if currentcell < 0 [set currentcell 0]

    ;; finally set the cell number
    set cellnumber currentcell

    ;; if we want to see the probablity density
    ifelse showprobdensity
     [
        ;; set the probablity a target is in this cell
        set prob matrix:get probdensity cellnumber 0

        ;; set the color to scale
        set pcolor scale-color blue prob 0 max matrix:get-column probdensity 0
      ]

     ;; otherwise set everything to black
     [ set pcolor black ]

     ;; if we want to see the patch number
     if showcellnumber
     [
       set plabel cellnumber
       set plabel-color black
       ]

     ;; if we want to see the probablity density label per patch
     if showcellproblabel
     [
       set plabel precision (matrix:get probdensity cellnumber 0) 3
       set plabel-color black
       ]

    ]
end

;; update the patches
to update-patches
  ask patches [
    ;; if we want to see the probably density
    if showprobdensity
    [
      ;; get the probablity that a target is in the cell
      set prob matrix:get probdensity cellnumber 0

      ;; set the color to scale
      set pcolor scale-color blue prob 0 max matrix:get-column probdensity 0
      ]

    ;; if we want to see the probablity density label per patch
    if showcellproblabel
    [
      set plabel precision (matrix:get probdensity cellnumber 0) 3
      set plabel-color black
      ]

  ]
end


