;;update the searchers ideal transition matrix according to new data
to update-searcher-idea-transitionmatrix

    if ((targetseenat != 0 and targetmovedto != 0) or time = 0) and (searcherstrat = "myidea - gangster1" or searcherstrat = "myidea - gangster2" or searcherstrat = "myidea - gangster3" or searcherstrat = "myidea - fugitive2")
    [
      ;;get generated data ie conform to generated data
      set-generated-dataset

      ;;for rows
      set k 0

      ;;for columns
      set j 0

      ;;loop through all rows and columns
      while [k <= 99]
        [
          while [j <= 99]
          [
          ;;rowcount variables
          set totalrows 0
          set fromrows 0
          set torows 0

          ;;get diminsion of data
          set datadim matrix:dimensions myideadata
          set totalrows first datadim

          set i 0
          while [i <= totalrows - 1]
          [
            ;;count where the target is coming from
            if matrix:get myideadata i 0 = k + 1
            [set fromrows fromrows + 1]

            ;;count wher the target is going to from that cell
            if matrix:get myideadata i 0 = k + 1 and matrix:get myideadata i 1 = j + 1
            [set torows torows + 1]

            set i i + 1
            ]

          ;;calculate new transition cell value
          set newtranscell torows / fromrows

          ;;set new value
          ifelse fromrows = 0
          [
            ;; if demominator is 0 set new value to zero
            matrix:set targetknowntransitionmatrix k j 0
            ]
          [
            matrix:set targetknowntransitionmatrix k j newtranscell
            ]


          set j j + 1
          ]
        set k k + 1
        ]

        ;;import assumptions
        ifelse searcherstrat = "myidea - gangster1"
          [
            ;;hideouts
            matrix:set-column targetknowntransitionmatrix 81 (map [ x1 -> x1 * 2 ] (matrix:get-column targetknowntransitionmatrix 81))
            matrix:set-column targetknowntransitionmatrix 88 (map [ x1 -> x1 * 2 ] (matrix:get-column targetknowntransitionmatrix 88))
            matrix:set-column targetknowntransitionmatrix 14 (map [ x1 -> x1 * 2 ] (matrix:get-column targetknowntransitionmatrix 14))

            ;;places to avoid
            matrix:set-column targetknowntransitionmatrix 1 (map [ x1 -> x1 * 0.1 ] (matrix:get-column targetknowntransitionmatrix 1))
            matrix:set-column targetknowntransitionmatrix 31 (map [ x1 -> x1 * 0.1 ] (matrix:get-column targetknowntransitionmatrix 31))
            matrix:set-column targetknowntransitionmatrix 19 (map [ x1 -> x1 * 0.1 ] (matrix:get-column targetknowntransitionmatrix 19))

            ;;country to avoid
            set i 0
            while [i < gridsize / 2]
               [
                 matrix:set-column targetknowntransitionmatrix i (map [ x1 -> x1 * 0.01 ] (matrix:get-column targetknowntransitionmatrix i))
                 set i i + 1
               ]

             ;;country to stay in
             set i gridsize / 2
             while [i < gridsize]
               [
                 matrix:set-column targetknowntransitionmatrix i (map [ x1 -> x1 * 10 ] (matrix:get-column targetknowntransitionmatrix i))
                 set i i + 1
               ]



             ]
         [ ifelse searcherstrat = "myidea - gangster2"
          [
             ;;hideouts
             matrix:set-column targetknowntransitionmatrix 61 (map [ x1 -> x1 * 1.2 ] (matrix:get-column targetknowntransitionmatrix 81))
             matrix:set-column targetknowntransitionmatrix 88 (map [ x1 -> x1 * 1.2 ] (matrix:get-column targetknowntransitionmatrix 88))
             matrix:set-column targetknowntransitionmatrix 27 (map [ x1 -> x1 * 1.2 ] (matrix:get-column targetknowntransitionmatrix 14))

             ;;places to avoid
             matrix:set-column targetknowntransitionmatrix 0 (map [ x1 -> x1 * 0.5 ] (matrix:get-column targetknowntransitionmatrix 1))
             matrix:set-column targetknowntransitionmatrix 21 (map [ x1 -> x1 * 0.5 ] (matrix:get-column targetknowntransitionmatrix 31))
             matrix:set-column targetknowntransitionmatrix 54 (map [ x1 -> x1 * 0.5 ] (matrix:get-column targetknowntransitionmatrix 31))
             matrix:set-column targetknowntransitionmatrix 91 (map [ x1 -> x1 * 0.5 ] (matrix:get-column targetknowntransitionmatrix 19))

             matrix:set-column targetknowntransitionmatrix 1 (map [ x1 -> x1 * 0.9 ] (matrix:get-column targetknowntransitionmatrix 1))
             matrix:set-column targetknowntransitionmatrix 11 (map [ x1 -> x1 * 0.9 ] (matrix:get-column targetknowntransitionmatrix 31))
             matrix:set-column targetknowntransitionmatrix 10 (map [ x1 -> x1 * 0.9 ] (matrix:get-column targetknowntransitionmatrix 31))
             matrix:set-column targetknowntransitionmatrix 20 (map [ x1 -> x1 * 0.9 ] (matrix:get-column targetknowntransitionmatrix 19))

             ]
          [ ifelse searcherstrat = "myidea - fugitive2"
            [
            ;;hideouts
            matrix:set-column targetknowntransitionmatrix 64 (map [ x1 -> x1 * 2 ] (matrix:get-column targetknowntransitionmatrix 64))

            set i 0
            while [i < 10]
               [
                 matrix:set-column targetknowntransitionmatrix i (map [ x1 -> x1 * 2 ] (matrix:get-column targetknowntransitionmatrix i))
                 matrix:set-column targetknowntransitionmatrix i + 90 (map [ x1 -> x1 * 2 ] (matrix:get-column targetknowntransitionmatrix (i + 90)))
                 matrix:set-column targetknowntransitionmatrix i * 10 (map [ x1 -> x1 * 2 ] (matrix:get-column targetknowntransitionmatrix (i * 10)))
                 matrix:set-column targetknowntransitionmatrix i * 10 + 9 (map [ x1 -> x1 * 2 ] (matrix:get-column targetknowntransitionmatrix (i * 10 + 9)))
                 set i i + 1
               ]

             ;;places to avoid
             matrix:set-column targetknowntransitionmatrix 32 (map [ x1 -> x1 * 0.5 ] (matrix:get-column targetknowntransitionmatrix 32))
             matrix:set-column targetknowntransitionmatrix 42 (map [ x1 -> x1 * 0.5 ] (matrix:get-column targetknowntransitionmatrix 42))
             matrix:set-column targetknowntransitionmatrix 66 (map [ x1 -> x1 * 0.5 ] (matrix:get-column targetknowntransitionmatrix 66))
             matrix:set-column targetknowntransitionmatrix 77 (map [ x1 -> x1 * 0.9 ] (matrix:get-column targetknowntransitionmatrix 77))

             ;;will not cross
             matrix:set targetknowntransitionmatrix 67 68 0
             matrix:set targetknowntransitionmatrix 57 58 0
             matrix:set targetknowntransitionmatrix 47 48 0
             matrix:set targetknowntransitionmatrix 37 38 0
