to move-searchers
  ask searchers [

    ;;if baysian search
    if searcherstrat = "baysian" or searcherstrat = "myidea - gangster1" or searcherstrat = "myidea - gangster2" or searcherstrat = "myidea - fugitive2"
     [
       ;;set up a empty prob matrix
       set probdensitymatrix matrix:make-constant 100 100 0

       ;;initialize counter to 0
       set k 0
       while [k <= 99]
          [
            ;;fill probablity matrix with probablities
            matrix:set-row probdensitymatrix k matrix:get-column probdensity 0
            set k k + 1

           ]

       ;;set searcher transition matrix to current probablity matrix
       set searchertransitionmatrix matrix:times-element-wise probdensitymatrix associationmatrix
       ]

    ;;get currentcell from patch
    ask patch-here [ set currentcell cellnumber]

    ;; get current x and y
    set currentx xcor
    set currenty ycor

    ;;get neighboring cell probablities
    ;;note expanding probablites to 100
    ;show "time"
    ;show time
    ifelse (currentcell - gridlength - 1) >= 0 and (currentcell - gridlength - 1 + 1) mod 10 != 0
      [set cell1 (matrix:get searchertransitionmatrix (currentcell) (currentcell - gridlength - 1)) * 100]
      [set cell1 0]
    ifelse (currentcell - gridlength) >= 0
      [set cell2 (matrix:get searchertransitionmatrix (currentcell) (currentcell - gridlength)) * 100]
      [set cell2 0]
    ifelse (currentcell - gridlength + 1) >= 0 and (currentcell - gridlength + 1) mod 10 != 0
      [set cell3 (matrix:get searchertransitionmatrix (currentcell) (currentcell - gridlength + 1)) * 100]
      [set cell3 0]
    ifelse (currentcell - 1) >= 0  and (currentcell - 1 + 1) mod 10 != 0
      [set cell4 (matrix:get searchertransitionmatrix (currentcell) (currentcell - 1)) * 100]
      [set cell4 0]
    ifelse (currentcell) >= 0
      [set cell5 (matrix:get searchertransitionmatrix (currentcell) (currentcell)) * 100]
      [set cell5 0]
    ifelse (currentcell + 1)  < gridsize and (currentcell + 1) mod 10 != 0
      [set cell6 (matrix:get searchertransitionmatrix (currentcell) (currentcell + 1)) * 100]
      [set cell6 0]
    ifelse (currentcell + gridlength - 1) < gridsize and (currentcell + gridlength - 1 + 1) mod 10 != 0
      [set cell7 (matrix:get searchertransitionmatrix (currentcell) (currentcell + gridlength - 1)) * 100]
      [set cell7 0]
    ifelse (currentcell + gridlength)  < gridsize
      [set cell8 (matrix:get searchertransitionmatrix (currentcell) (currentcell + gridlength)) * 100]
      [set cell8 0]
    ifelse (currentcell + gridlength + 1)  < gridsize and (currentcell + gridlength + 1) mod 10 != 0
      [set cell9 (matrix:get searchertransitionmatrix (currentcell) (currentcell + gridlength + 1)) * 100]
      [set cell9 0]

    ;;if we are using a baysian, myidea, or mowing grow
    ifelse searcherstrat = "baysian" OR searcherstrat = "mowing" or searcherstrat = "myidea - gangster1" or searcherstrat = "myidea - gangster2" or searcherstrat = "myidea - fugitive2"
       [
         ;;set heading to 0
         set heading 90

         ;;find max cell probablity
         set cellmax max (list cell1 cell2 cell3 cell4 cell5 cell6 cell7 cell8 cell9)

         ;;find what cell has the max probablity then move there
         ifelse cellmax = cell1 and cell1taken = 0
           [left 225 forward 1
             ifelse any? other searchers-here
             [ set cell1taken 1 setxy currentx currenty move-searchers]
             [move-to patch-here]
             ]
           [ifelse cellmax = cell2 and cell2taken = 0
             [left 270 forward 1
               ifelse any? other searchers-here
               [ set cell2taken 1 setxy currentx currenty move-searchers]
               [move-to patch-here]
               ]
             [ifelse cellmax = cell3 and cell3taken = 0
               [left 315 forward 1
                 ifelse any? other searchers-here
                 [ set cell3taken 1 setxy currentx currenty move-searchers]
                 [move-to patch-here]
                 ]
               [ifelse cellmax = cell4 and cell4taken = 0
                 [left 180 forward 1
                  ifelse any? other searchers-here
                  [ set cell4taken 1 setxy currentx currenty move-searchers]
                  [move-to patch-here]
                  ]
                 [ifelse cellmax = cell5  and cell5taken = 0
                   [left 0 forward 0
                     ifelse any? other searchers-here
                     [ set cell5taken 1 setxy currentx currenty move-searchers]
                     [move-to patch-here]
                     ]
                   [ifelse cellmax = cell6 and cell6taken = 0
                     [left 0 forward 1
                       ifelse any? other searchers-here
                       [ set cell6taken 1 setxy currentx currenty move-searchers]
                       [move-to patch-here]
                       ]
                     [ifelse cellmax = cell7 and cell7taken = 0
                       [left 135 forward 1
                         ifelse any? other searchers-here
                         [ set cell7taken 1 setxy currentx currenty move-searchers]
                         [move-to patch-here]
                         ]
                       [ifelse cellmax = cell8 and cell8taken = 0
                         [left 90 forward 1
                           ifelse any? other searchers-here
                           [ set cell8taken 1 setxy currentx currenty move-searchers]
                           [move-to patch-here]
                           ]
                         [ifelse cellmax = cell9 and cell9taken = 0
                           [left 45 forward 1
                             ifelse any? other searchers-here
                             [ set cell9taken 1 setxy currentx currenty move-searchers]
                             [move-to patch-here]
                             ]
                           [setxy currentx currenty move-to patch-here ]
                         ]
                        ]
                       ]
                     ]
                   ]
                 ]
               ]
             ]

         ]
       [
          ;;find cell summations to find random picking boundaries
          set sumcell1 cell1
          set sumcell2 sumcell1 + cell2
          set sumcell3 sumcell2 + cell3
          set sumcell4 sumcell3 + cell4
          set sumcell5 sumcell4 + cell5
          set sumcell6 sumcell5 + cell6
          set sumcell7 sumcell6 + cell7
          set sumcell8 sumcell7 + cell8
          set sumcell9 sumcell8 + cell9

          ;;get a random number based on total sum
          set randomcell random sumcell9

          ;;set heading to 0
          set heading 90

          ;;find where the random number lands within the probablity boundaries
          ifelse randomcell >= 0 and randomcell <= sumcell1
           [left 225 forward 1 ]
           [ifelse randomcell > sumcell1 and randomcell <= sumcell2
             [left 270 forward 1 ]
             [ifelse randomcell > sumcell2 and randomcell <= sumcell3
               [left 315 forward 1 ]
               [ifelse randomcell > sumcell3 and randomcell <= sumcell4
                 [left 180 forward 1 ]
                 [ifelse randomcell > sumcell4 and randomcell <= sumcell5
                   [left 0 forward 0 ]
                   [ifelse randomcell > sumcell5 and randomcell <= sumcell6
                     [left 0 forward 1 ]
                     [ifelse randomcell > sumcell6 and randomcell <= sumcell7
                       [left 135 forward 1 ]
                       [ifelse randomcell > sumcell7 and randomcell <= sumcell8
                         [left 90 forward 1 ]
                         [if randomcell > sumcell8 and randomcell <= sumcell9
                           [left 45 forward 1 ]
                           ]
                         ]
                       ]
                     ]
                   ]
                 ]
               ]
             ]

          ;; move to center of patch
          move-to patch-here

        ]
     ]


end

to move-targets
  ask targets [
    ;;ask if caught
    ;;if not caught move target according to transition matrix
    ifelse caught = 0
    [

    ;;get currentcell from patch
    ask patch-here [ set currentcell cellnumber]

    ;;get neighboring cell probablities
    ;;note expanding probablites to 100
    ifelse (currentcell - gridlength - 1) > 0 and (currentcell - gridlength - 1 + 1) mod 10 != 0
      [set cell1 (matrix:get targettransitionmatrix (currentcell) (currentcell - gridlength - 1)) * 100]
      [set cell1 0]
    ifelse (currentcell - gridlength) > 0
      [set cell2 (matrix:get targettransitionmatrix (currentcell) (currentcell - gridlength)) * 100]
      [set cell2 0]
    ifelse (currentcell - gridlength + 1) > 0 and (currentcell - gridlength + 1) mod 10 != 0
      [set cell3 (matrix:get targettransitionmatrix (currentcell) (currentcell - gridlength + 1)) * 100]
      [set cell3 0]
    ifelse (currentcell - 1) > 0  and (currentcell - 1 + 1) mod 10 != 0
      [set cell4 (matrix:get targettransitionmatrix (currentcell) (currentcell - 1)) * 100]
      [set cell4 0]
    ifelse (currentcell) > 0
      [set cell5 (matrix:get targettransitionmatrix (currentcell) (currentcell)) * 100]
      [set cell5 0]
    ifelse (currentcell + 1)  < gridsize and (currentcell + 1) mod 10 != 0
      [set cell6 (matrix:get targettransitionmatrix (currentcell) (currentcell + 1)) * 100]
      [set cell6 0]
    ifelse (currentcell + gridlength - 1) < gridsize and (currentcell + gridlength - 1 + 1) mod 10 != 0
      [set cell7 (matrix:get targettransitionmatrix (currentcell) (currentcell + gridlength - 1)) * 100]
      [set cell7 0]
    ifelse (currentcell + gridlength)  < gridsize
      [set cell8 (matrix:get targettransitionmatrix (currentcell) (currentcell + gridlength)) * 100]
      [set cell8 0]
    ifelse (currentcell + gridlength + 1)  < gridsize and (currentcell + gridlength + 1) mod 10 != 0
      [set cell9 (matrix:get targettransitionmatrix (currentcell) (currentcell + gridlength + 1)) * 100]
      [set cell9 0]

    ;;find cell summations to find random picking boundaries
    set sumcell1 cell1
    set sumcell2 sumcell1 + cell2
    set sumcell3 sumcell2 + cell3
    set sumcell4 sumcell3 + cell4
    set sumcell5 sumcell4 + cell5
    set sumcell6 sumcell5 + cell6
    set sumcell7 sumcell6 + cell7
    set sumcell8 sumcell7 + cell8
    set sumcell9 sumcell8 + cell9
    set randomcell random sumcell9

    ;;set heading to 0
    set heading 90

    ;;find where the random number lands within the probablity boundaries
    ifelse randomcell >= 0 and randomcell <= sumcell1
        [left 225 forward 1 ]
        [ifelse randomcell > sumcell1 and randomcell <= sumcell2
          [left 270 forward 1 ]
          [ifelse randomcell > sumcell2 and randomcell <= sumcell3
            [left 315 forward 1 ]
            [ifelse randomcell > sumcell3 and randomcell <= sumcell4
              [left 180 forward 1 ]
              [ifelse randomcell > sumcell4 and randomcell <= sumcell5
                [left 0 forward 0 ]
                [ifelse randomcell > sumcell5 and randomcell <= sumcell6
                  [left 0 forward 1 ]
                  [ifelse randomcell > sumcell6 and randomcell <= sumcell7
                    [left 135 forward 1 ]
                    [ifelse randomcell > sumcell7 and randomcell <= sumcell8
                      [left 90 forward 1 ]
                      [if randomcell > sumcell8 and randomcell <= sumcell9
                        [left 45 forward 1 ]
                          ]
                         ]
                       ]
                     ]
                   ]
                 ]
               ]
             ]

        ;; move to center of patch
        move-to patch-here

        ;; if just seen show next move
        if justseen = 1
          [

          ;;find cell that the target moved to
          ask patch-here [ set currentcell cellnumber]

          ;;report that cell
          show "target just moved to patch"
          show currentcell
          set targetmovedto currentcell

          ;;update the searchers ideal transition matrix according to new data
          if searcherstrat = "myidea - gangster1" or searcherstrat = "myidea - gangster2" or searcherstrat = "myidea - fugitive2"
          [update-searcher-idea-transitionmatrix]

          ;;set justseen to 0
          set justseen 0
          ]

      ]
    ;;if caught change color to red and dont move
    [set color red ]


  ]
end

;; move sensors
to move-sensors

  ;; if sensors are allowed to move
  if sensorsmove [

     ;; make sensors move randomly
     ask sensors [

       ;;change heading
       right random 360

       ;;move one unit
       forward 1
       ]
  ]
end

;; see if a target has been caught
to target-caught
  ;;if searchers are allowed to catch targets
  ifelse TargetsCatch

  ;; if it is allowed to catch targets
  [ ifelse exponentialdetection

     ;; if useing exponential detection
     [ask targets with [(1 - exp (-1 * detectionrate * (count searchers-here))) * (count searchers-here) * 100 > random 100]
       [
         set caught 1

         ;;set the flag for just seen
         set justseen 1

         ;;find the cell that the target was seen
         ask patch-here [ set currentcell cellnumber]

         ;;print where you seen the target
         show "target seen at patch"
         show currentcell

         ;;report the cell number
         set targetseenat currentcell
         ]
       ]

     ;; if using deterministic detection
     [ask targets with [count searchers-here > 0]
       [
         set caught 1

         ;;set the flag for just seen
         set justseen 1

         ;;find the cell that the target was seen
         ask patch-here [ set currentcell cellnumber]

         ;;print where you seen the target
         show "target seen at patch"
         show currentcell

         ;;report the cell number
         set targetseenat currentcell

         ]
       ] ;; if in same
  ]

  ;;otherwise treat as if the searcher is a sensor
  [ ifelse exponentialdetection

     ;; if using exponential detection
     [ask targets with [(1 - exp (-1 * detectionrate * (count searchers-here))) * (count searchers-here) * 100 > random 100]
       [
         set seen 1
         set color grey

         ;;set the flag for just seen
         set justseen 1

         ;;find the cell that the target was seen
         ask patch-here [ set currentcell cellnumber]

         ;;print where you seen the target
         show "target seen at patch"
         show currentcell

         ;;report the cell number
         set targetseenat currentcell
         ]
       ]

     ;; if using deterministic detection
     [ask targets with [count searchers-here > 0]
       [
         set seen 1
         set color grey
         set justseen 1

         ;;print where you seen the target
         ask patch-here [ set currentcell cellnumber]
         show "target seen at patch"
         show currentcell
         ]
       ] ;; if in same cell set to seen
  ]
end

;; if a target has been seen by a sensor
to target-seen
 ;; if we are using exponential detection
 ifelse exponentialdetection
     [
       ;; ask targets if there in the same cell as a sensor and the probablity is not in their favor
       ask targets with [(1 - exp (-1 * detectionrate * (count sensors-here))) * (count sensors-here) * 100 > random 100]
       [
         ;; if seen set target variable seen to 1 and set color to grey
         set seen 1
         set color grey

         ;;set the flag for just seen
         set justseen 1

         ;;find the cell that the target was seen
         ask patch-here [ set currentcell cellnumber]

         ;;print where you seen the target
         show "target seen at patch"
         show currentcell

         ;;report the cell number
         set targetseenat currentcell

         ;;if we are reporting targets update the probability density
         if SensorsReportTarget and caught = 0
         [
           ;;get currentcell from patch
           ask patch-here [ set currentcell cellnumber]

           ;;update prob density 100% there is a target here
           matrix:set probdensity currentcell 0 1
           ]
         ]
       ]
     [
       ;; otherwise use deterministic detection and the target is seen
       ask targets with [count sensors-here > 0]
       [
